package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.internal.*;import javax.swing.*;import java.awt.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.*;
public final class TargetCleanupTest extends WorkbenchTest {
 static Object field(Object o,String name){try{return get(o,name);}catch(Exception ex){throw new RuntimeException(ex);}}
 static JButton find(Component c,String text){if(c instanceof JButton b&&b.getText().equals(text))return b;if(c instanceof Container p)for(Component child:p.getComponents()){JButton b=find(child,text);if(b!=null)return b;}return null;}
 public static void main(String[] args)throws Exception {
  ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->def(m));MontoyaApi api=(MontoyaApi)PayloadIntegrationTest.host(MontoyaApi.class);WorkbenchExtension ext=new WorkbenchExtension();ext.initialize(api);WorkbenchScope rules=(WorkbenchScope)get(ext,"localScope");rules.add("https://clean.test/",true);JsAnalysisPanel js=(JsAnalysisPanel)get(ext,"jsAnalysis");EnvironmentPanel env=(EnvironmentPanel)get(ext,"environments");PassiveScanWorkspace urls=(PassiveScanWorkspace)get(ext,"passiveScan");ActivityPanel activity=(ActivityPanel)get(ext,"activity");JTabbedPane tabs=(JTabbedPane)get(ext,"tabs");AtomicReference<Component> content=new AtomicReference<>();AtomicInteger opened=new AtomicInteger();TargetWindow[] windows={(TargetWindow)get(js,"targetSettings"),(TargetWindow)get(env,"targetSettings"),(TargetWindow)get(urls,"targetSettings")};for(TargetWindow w:windows)w.opener=(owner,title,body,modal,close)->{check(!modal,"target dialog is modeless");content.set(body);opened.incrementAndGet();return null;};
  edt(()->{
   check(!SwingUtilities.isDescendingFrom(js.sourceUrl,js),"JS source URL input removed from main page");check(!SwingUtilities.isDescendingFrom(env.origins,env),"environment target selector removed from main page");check(!SwingUtilities.isDescendingFrom(urls.input,urls),"URL collection target input removed from main page");check(SwingUtilities.isDescendingFrom(activity.search,activity),"activity record search remains accessible");
   tabs.setSelectedComponent(js);int selected=tabs.getSelectedIndex();find(js,"대상 설정").doClick();check(tabs.getSelectedIndex()==selected,"JS target dialog preserves selected tool");check(SwingUtilities.isDescendingFrom(js.sourceUrl,content.get()),"JS source URL is available inside target dialog");JComboBox<?> combo=(JComboBox<?>)UiLayoutTest.named(content.get(),"wb.target.scope.choices");check(combo.getItemCount()==2,"target dialog offers registered SCOPE");combo.setSelectedIndex(1);check(js.sourceUrl.getText().equals("https://clean.test/"),"SCOPE choice populates JS relative URL base");check(((JLabel)field(js,"sourceSummary")).getText().contains("clean.test"),"JS summary reflects configured source");
   rules.add("https://next.test/",true);windows[0].open();check(((JComboBox<?>)UiLayoutTest.named(content.get(),"wb.target.scope.choices")).getItemCount()==3,"reopened target dialog reads current SCOPE list");
   env.observe(request("https://clean.test/a","GET",false,List.of()),response(200,"{}"));tabs.setSelectedComponent(env);selected=tabs.getSelectedIndex();find(env,"대상 설정").doClick();check(tabs.getSelectedIndex()==selected&&SwingUtilities.isDescendingFrom(env.origins,content.get()),"environment selector opens without switching tool");((JComboBox<?>)UiLayoutTest.named(content.get(),"wb.target.scope.choices")).setSelectedIndex(1);check(env.origins.getSelectedItem().equals("https://clean.test"),"environment SCOPE choice resolves observed origin");
   tabs.setSelectedComponent(urls);selected=tabs.getSelectedIndex();find(urls,"대상 설정").doClick();check(tabs.getSelectedIndex()==selected&&SwingUtilities.isDescendingFrom(urls.input,content.get()),"URL target entry opens separately without navigation");((JComboBox<?>)UiLayoutTest.named(content.get(),"wb.target.scope.choices")).setSelectedIndex(1);find(content.get(),"대상 열기").doClick();check(urls.panels.size()==1&&((PassiveScanPanel)urls.targets.getSelectedComponent()).job==null,"choosing a target prepares tab without collecting or sending traffic");PassiveScanPanel first=(PassiveScanPanel)urls.targets.getSelectedComponent();check(!SwingUtilities.isDescendingFrom(first.target,first),"duplicate domain input removed from target result page");check(first.target.getText().equals("clean.test"),"collector retains correct domain internally");
   urls.open("https://clean.test/second",false);urls.targets.setSelectedComponent(first);urls.input.setText("https://next.test/draft");check(!((JLabel)field(urls,"targetSummary")).getText().contains("next.test"),"unapplied input never changes active target summary");first.source.setSelectedItem("Burp History / JS");find(urls,"대상 수집 시작").doClick();check(urls.targets.getSelectedComponent()==first&&urls.panels.size()==2,"main collect action uses active tab rather than pending target text");
  });PassiveScanTest.idle((PassiveScanPanel)urls.targets.getSelectedComponent());check(PayloadIntegrationTest.sent.get()==0,"target configuration and passive history selection send no target HTTP requests");for(var h:PayloadIntegrationTest.modernUnloads)h.extensionUnloaded();edt(()->{});int before=opened.get();edt(()->{for(TargetWindow w:windows)w.open();});check(opened.get()==before,"unloaded target settings cannot reopen");System.out.println("TargetCleanupTest: "+checks+" checks passed");
 }
}
